function nextRoundInfo() {
  const parts = getMyanmarParts();
  const currentMinutes = parts.hour * 60 + parts.minute;
  let next = ROUND_SCHEDULE.find((item) => item.minutes >= currentMinutes);
  let dayText = "ဒီနေ့";
  let remaining;

  if (next) {
    remaining = next.minutes - currentMinutes;
  } else {
    next = ROUND_SCHEDULE[0];
    dayText = "မနက်ဖြန်";
    remaining = 24 * 60 - currentMinutes + next.minutes;
  }

  return { next, dayText, remaining };
}

function timesMessage() {
  const next = nextRoundInfo();
  const lines = ["🕘 New Zealand 2D ထွက်ချိန်များ", ""];
  for (const item of ROUND_SCHEDULE) lines.push(`${item.icon} ${item.time}`);
  lines.push(
    "",
    "တစ်နေ့လျှင် စုစုပေါင်း ၆ ကြိမ်",
    "",
    `⏳ နောက်တစ်ကြိမ် — ${next.dayText} ${next.next.time}`,
    `⌛ ကျန်ချိန် — ${next.remaining === 0 ? "အခု" : `${next.remaining} မိနစ်`}`
  );
  return lines.join("\n");
}

