function isAdmin(env, userId) {
  const ids = String(env.ADMIN_USER_ID || "")
    .split(",")
    .map((value) => value.trim())
    .filter(Boolean);
  return ids.includes(String(userId));
}

async function createBroadcastDraft(env, message) {
  if (!isAdmin(env, message.from?.id)) {
    await telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: message.chat.id,
      text: "⛔ ဒီ Command ကို Admin သာ အသုံးပြုနိုင်ပါတယ်။ /myid နဲ့ ID ကြည့်ပြီး Cloudflare မှာ ADMIN_USER_ID ထည့်ပါ။",
    });
    return;
  }

  const rawText = String(message.text || "");
  let text = rawText.replace(/^\/broadcast(?:@\w+)?\s*/i, "").trim();
  if (!text) text = String(message.reply_to_message?.text || message.reply_to_message?.caption || "").trim();

  if (!text) {
    await telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: message.chat.id,
      text: "အသုံးပြုပုံ—\n/broadcast ကြေညာချက်စာသား\n\nစာတစ်စောင်ကို Reply လုပ်ပြီး /broadcast လို့လည်း ပို့နိုင်ပါတယ်။",
    });
    return;
  }

  if (text.length > 3500) {
    await telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: message.chat.id,
      text: "Broadcast စာသား ၃၅၀၀ လုံးထက် မကျော်ရပါ။",
    });
    return;
  }

  const id = crypto.randomUUID().replaceAll("-", "").slice(0, 16);
  await env.DB.prepare(`
    INSERT INTO broadcast_drafts (id, admin_user_id, text, status)
    VALUES (?, ?, ?, 'pending')
  `).bind(id, message.from.id, text).run();

  await telegramRequest(env.BOT_TOKEN, "sendMessage", {
    chat_id: message.chat.id,
    text: `📢 Broadcast Preview\n\n${text}\n\nအတည်ပြုပြီးရင် Cron က အများဆုံး ၂ မိနစ်အတွင်း စတင်ပို့ပါမယ်။`,
    reply_markup: {
      inline_keyboard: [[
        { text: "✅ ပို့မည်", callback_data: `broadcast_confirm:${id}` },
        { text: "❌ မပို့တော့ပါ", callback_data: `broadcast_cancel:${id}` },
      ]],
    },
  });
}

async function queueBroadcast(env, callbackQuery, id) {
  const userId = callbackQuery.from?.id;
  if (!isAdmin(env, userId)) {
    await telegramRequest(env.BOT_TOKEN, "answerCallbackQuery", {
      callback_query_id: callbackQuery.id,
      text: "Admin မဟုတ်ပါ",
      show_alert: true,
    });
    return;
  }

  const result = await env.DB.prepare(`
    UPDATE broadcast_drafts SET status = 'queued', updated_at = CURRENT_TIMESTAMP
    WHERE id = ? AND admin_user_id = ? AND status = 'pending'
  `).bind(id, userId).run();

  await telegramRequest(env.BOT_TOKEN, "answerCallbackQuery", {
    callback_query_id: callbackQuery.id,
    text: Number(result?.meta?.changes || 0) > 0 ? "Broadcast တန်းစီပြီးပါပြီ" : "ဒီ Broadcast ကို ပြင်ပြီး/ပို့ပြီးသားပါ",
  });

  if (callbackQuery.message?.chat?.id && callbackQuery.message?.message_id) {
    await telegramRequest(env.BOT_TOKEN, "editMessageReplyMarkup", {
      chat_id: callbackQuery.message.chat.id,
      message_id: callbackQuery.message.message_id,
      reply_markup: { inline_keyboard: [] },
    });
  }
}

async function cancelBroadcast(env, callbackQuery, id) {
  const userId = callbackQuery.from?.id;
  if (!isAdmin(env, userId)) return;
  await env.DB.prepare(`
    UPDATE broadcast_drafts SET status = 'cancelled', updated_at = CURRENT_TIMESTAMP
    WHERE id = ? AND admin_user_id = ? AND status = 'pending'
  `).bind(id, userId).run();
  await telegramRequest(env.BOT_TOKEN, "answerCallbackQuery", {
    callback_query_id: callbackQuery.id,
    text: "Broadcast ပယ်ဖျက်ပြီးပါပြီ",
  });
  if (callbackQuery.message?.chat?.id && callbackQuery.message?.message_id) {
    await telegramRequest(env.BOT_TOKEN, "editMessageReplyMarkup", {
      chat_id: callbackQuery.message.chat.id,
      message_id: callbackQuery.message.message_id,
      reply_markup: { inline_keyboard: [] },
    });
  }
}

async function processQueuedBroadcast(env) {
  await env.DB.prepare(`
    UPDATE broadcast_drafts SET status = 'queued', updated_at = CURRENT_TIMESTAMP
    WHERE status = 'sending' AND updated_at < datetime('now', '-20 minutes')
  `).run();

  const draft = await env.DB.prepare(`
    SELECT id, admin_user_id, text
    FROM broadcast_drafts
    WHERE status = 'queued'
    ORDER BY created_at
    LIMIT 1
  `).first();
  if (!draft) return null;

  const claimed = await env.DB.prepare(`
    UPDATE broadcast_drafts SET status = 'sending', updated_at = CURRENT_TIMESTAMP
    WHERE id = ? AND status = 'queued'
  `).bind(draft.id).run();
  if (Number(claimed?.meta?.changes || 0) === 0) return null;

  try {
    const stats = await broadcastToSubscribers(env, `📢 New Zealand 2D အသိပေးချက်\n\n${draft.text}`);
    await env.DB.prepare(`
      UPDATE broadcast_drafts SET
        status = 'sent', total_count = ?, sent_count = ?, failed_count = ?,
        sent_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `).bind(stats.total, stats.sent, stats.failed, draft.id).run();

    try {
      await telegramRequest(env.BOT_TOKEN, "sendMessage", {
        chat_id: draft.admin_user_id,
        text: `✅ Broadcast ပြီးပါပြီ\n\nစုစုပေါင်း — ${stats.total}\nပို့ပြီး — ${stats.sent}\nမအောင်မြင် — ${stats.failed}\nInactive — ${stats.inactive}`,
      });
    } catch (error) {
      console.error("Could not send broadcast report", error);
    }
    return stats;
  } catch (error) {
    await env.DB.prepare(`
      UPDATE broadcast_drafts SET status = 'failed', updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `).bind(draft.id).run();
    throw error;
  }
}

async function handleCallback(env, callbackQuery, origin) {
  const data = String(callbackQuery.data || "");
  const chatId = callbackQuery.message?.chat?.id;

  if (data === "refresh_live") return refreshLiveMessage(env, callbackQuery);
  if (data.startsWith("broadcast_confirm:")) {
    return queueBroadcast(env, callbackQuery, data.split(":")[1]);
  }
  if (data.startsWith("broadcast_cancel:")) {
    return cancelBroadcast(env, callbackQuery, data.split(":")[1]);
  }

  await telegramRequest(env.BOT_TOKEN, "answerCallbackQuery", {
    callback_query_id: callbackQuery.id,
  }).catch(() => {});

  if (data === "send_live" && chatId) return sendLiveMessage(env, chatId);
  if (data === "show_times" && chatId) {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: timesMessage(),
      reply_markup: timesKeyboard(),
    });
  }
  if (data === "show_status" && chatId) return sendStatus(env, chatId);
  if (data === "history_today" && chatId) return sendHistoryDay(env, chatId, todayMyanmar());
  if (data === "history_yesterday" && chatId) return sendHistoryDay(env, chatId, shiftCanonicalDate(todayMyanmar(), -1));
  if (data === "history_7d" && chatId) return sendSevenDayHistory(env, chatId);
  if (data === "show_help" && chatId) {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: helpMessage(),
      reply_markup: helpKeyboard(env),
    });
  }
  if (data === "show_privacy" && chatId) {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: privacyText(origin),
    });
  }
  if ((data === "notify_on" || data === "notify_off") && chatId) {
    const enabled = data === "notify_on";
    await setNotifications(env, chatId, enabled);
    if (callbackQuery.message?.message_id) {
      await telegramRequest(env.BOT_TOKEN, "editMessageReplyMarkup", {
        chat_id: chatId,
        message_id: callbackQuery.message.message_id,
        reply_markup: welcomeKeyboard(enabled),
      }).catch(() => {});
    }
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: enabled ? "🔔 Result နဲ့ ကြေညာချက်အသိပေးခြင်း ဖွင့်ပြီးပါပြီ။" : "🔕 Result နဲ့ ကြေညာချက်အသိပေးခြင်း ပိတ်ပြီးပါပြီ။",
    });
  }
  if (data === "delete_me_confirm" && chatId) {
    await env.DB.prepare("DELETE FROM subscribers WHERE chat_id = ?").bind(chatId).run();
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: "✅ မိမိ Subscriber ဒေတာကို ဖျက်ပြီးပါပြီ။ ပြန်အသုံးပြုလိုရင် /start ကိုနှိပ်ပါ။",
    });
  }
  if (data === "delete_me_cancel" && chatId) {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: "ဒေတာဖျက်ခြင်း ပယ်ဖျက်ပြီးပါပြီ။",
    });
  }
  return null;
}

function commandFromText(text) {
  return String(text || "").trim().split(/\s+/)[0].toLowerCase().split("@")[0];
}

async function handleMessage(env, message, origin) {
  const chatId = message?.chat?.id;
  if (!chatId) return;
  const command = commandFromText(message.text);

  if (command === "/start") return sendWelcomePhoto(env, chatId, origin);
  if (command === "/live") return sendLiveMessage(env, chatId);
  if (command === "/history") return sendHistoryDay(env, chatId, todayMyanmar());
  if (command === "/times") {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: timesMessage(),
      reply_markup: timesKeyboard(),
    });
  }
  if (command === "/status") return sendStatus(env, chatId);
  if (command === "/help" || command === "/faq" || command === "/contact") {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: helpMessage(),
      reply_markup: helpKeyboard(env),
    });
  }
  if (command === "/notifications_on" || command === "/notifications_off") {
    const enabled = command === "/notifications_on";
    await setNotifications(env, chatId, enabled);
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: enabled ? "🔔 အသိပေးချက်ဖွင့်ပြီးပါပြီ။" : "🔕 အသိပေးချက်ပိတ်ပြီးပါပြီ။",
    });
  }
  if (command === "/privacy") {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: privacyText(origin),
    });
  }
  if (command === "/delete_me") {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: "မိမိ Subscriber ဒေတာကို တကယ်ဖျက်မလား?",
      reply_markup: {
        inline_keyboard: [[
          { text: "✅ ဖျက်မည်", callback_data: "delete_me_confirm" },
          { text: "❌ မဖျက်တော့ပါ", callback_data: "delete_me_cancel" },
        ]],
      },
    });
  }
  if (command === "/myid") {
    return telegramRequest(env.BOT_TOKEN, "sendMessage", {
      chat_id: chatId,
      text: `🆔 Your Telegram User ID — ${message.from?.id || "--"}\nChat ID — ${chatId}`,
    });
  }
  if (command === "/broadcast") return createBroadcastDraft(env, message);

  return telegramRequest(env.BOT_TOKEN, "sendMessage", {
    chat_id: chatId,
    text: "အောက်က Command တွေကို သုံးနိုင်ပါတယ်—\n/live /history /times /status /help",
    reply_markup: liveKeyboard(),
  });
}

async function handleUpdate(env, update, origin) {
  await ensureSchema(env);

  if (update.message) {
    await upsertSubscriber(env, update.message);
    await handleMessage(env, update.message, origin);
    return;
  }

  if (update.channel_post) {
  console.log(
    "CHANNEL POST RECEIVED:",
    JSON.stringify(update.channel_post)
  );

  const channel = update.channel_post.chat;

  if (channel?.id) {
    await addChannel(
      env,
      String(channel.id),
      channel.title || channel.username || ""
    );

      console.log(
        "Channel registered:",
        channel.id,
        channel.title || channel.username || ""
      );
    }

    return;
  }

  if (update.callback_query) {
    await upsertSubscriber(env, update.callback_query);
    await handleCallback(env, update.callback_query, origin);
  }
}

