async function runScheduled(env) {
  if (!env.BOT_TOKEN || !env.DB) {
    console.error("Scheduled run skipped: BOT_TOKEN or DB missing");
    return;
  }

  await ensureSchema(env);
  const locked = await acquireCronLock(env);
  if (!locked) {
    console.log("Scheduled run skipped because another run owns the lock");
    return;
  }

  try {
    try {
      const data = await fetchLiveState(env);
      const sync = await syncStateToDatabase(env, data, true);
      console.log("State sync complete", sync);
    } catch (error) {
      console.error("Scheduled state sync failed", error);
    }

        try {
  const autoPostResult = await autoPost(env);
  console.log("Auto post complete", autoPostResult);
} catch (error) {
  console.error(
    "AUTO_POST_ERROR_MESSAGE:",
    error?.message || String(error)
  );

  console.error(
    "AUTO_POST_ERROR_STACK:",
    error?.stack || "No stack"
  );
    }
    
    try {
      await processQueuedBroadcast(env);
    } catch (error) {
      console.error("Queued broadcast failed", error);
    }
  } finally {
    await releaseCronLock(env).catch((error) => console.error("Lock release failed", error));
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname === "/welcome-image") {
      return new Response(imageBytesFromBase64(), {
        headers: {
          "Content-Type": WELCOME_IMAGE_MIME,
          "Cache-Control": "public, max-age=3600",
        },
      });
    }

    if (url.pathname === "/privacy") {
      return new Response(privacyHtml(url.origin, env), {
        headers: { "Content-Type": "text/html; charset=UTF-8" },
      });
    }

    if (url.pathname === "/health") {
      return Response.json({
        ok: true,
        service: "New Zealand 2D Live Bot",
        database: DB_NAME,
        dbBound: Boolean(env.DB),
        botTokenConfigured: Boolean(env.BOT_TOKEN),
        webhookSecretConfigured: Boolean(env.WEBHOOK_SECRET),
        time: new Date().toISOString(),
      });
    }

    if (!env.BOT_TOKEN || !env.WEBHOOK_SECRET) {
      return new Response("BOT_TOKEN သို့မဟုတ် WEBHOOK_SECRET မရှိသေးပါ", { status: 500 });
    }

    if (request.method === "GET" && url.pathname === "/setup-webhook") {
      if (env.SETUP_KEY && url.searchParams.get("key") !== env.SETUP_KEY) {
        return new Response("Unauthorized setup key", { status: 401 });
      }
      try {
        const result = await setupWebhook(env, url.origin);
        return Response.json({
          ok: true,
          ...result,
          privacyUrl: `${url.origin}/privacy`,
          note: "Cron runs every 2 minutes after npm run deploy.",
        });
      } catch (error) {
        return Response.json({ ok: false, error: String(error.message || error) }, { status: 500 });
      }
    }

    if (request.method === "POST" && url.pathname === "/webhook") {
  const telegramSecret = request.headers.get(
    "X-Telegram-Bot-Api-Secret-Token"
  );

  if (telegramSecret !== env.WEBHOOK_SECRET) {
    return new Response("Unauthorized", { status: 401 });
  }

  try {
    const update = await request.json();

    console.log(
      "TELEGRAM UPDATE TYPE:",
      Object.keys(update)
    );

    ctx.waitUntil(
      handleUpdate(env, update, url.origin).catch((error) =>
        console.error("Webhook error", error)
      )
    );
  } catch (error) {
    console.error("Invalid webhook payload", error);
  }

  return new Response("OK");
    }

    return new Response("New Zealand 2D Live Bot is running");
  },

  async scheduled(controller, env, ctx) {
    await runScheduled(env);
  },
};



